<?php
namespace App\Services;
use Illuminate\Support\Str;
/** Shared decision authority; transport must supply validated moderator identity. */
final class Moderation {
 public function __construct(private GalleryStore $store,private \Closure $isModerator,private \Closure $clock){}
 private function now():int {return ($this->clock)();}
 private function staff(string $actor):void {abort_unless($actor!==''&&strlen($actor)<=128&&($this->isModerator)($actor)===true,403);}
 private function row(string $id){return $this->store->run('SELECT q.*,a.status FROM moderation_queue q JOIN artworks a ON a.id=q.artwork WHERE artwork=?',[$id])->fetch();}
 private function audit(string $id,string $actor,string $action,string $reason=''):void {$this->store->run('INSERT INTO moderation_audit(artwork,actor,action,reason,at) VALUES (?,?,?,?,?)',[$id,$actor,$action,$reason,$this->now()]);}
 private function publish(string $id):void {$this->store->run("UPDATE artworks SET status='published',visibility='public',publishedAt=? WHERE id=?",[gmdate('Y-m-d\TH:i:s',intdiv($this->now(),1000)).sprintf('.%03dZ',$this->now()%1000),$id]);}
 public function list(string $actor):array {$this->staff($actor);return $this->store->run("SELECT q.artwork,q.notification,q.delivered_at,q.due_at,q.revision,a.title,a.status,a.width,a.height,a.artist,p.name AS artist_name,d.description,d.submitted_at FROM moderation_queue q JOIN artworks a ON a.id=q.artwork JOIN artists p ON p.id=a.artist LEFT JOIN artwork_details d ON d.artwork=a.id WHERE a.status IN ('pending','held') ORDER BY a.rowid LIMIT 100")->fetchAll();}
 public function claim():?array {return $this->store->transaction(function(){$r=$this->store->run("SELECT q.artwork FROM moderation_queue q JOIN artworks a ON a.id=q.artwork WHERE q.notification='queued' AND q.retry_count<5 AND (q.retry_at IS NULL OR q.retry_at<=?) AND a.status='pending' ORDER BY a.rowid LIMIT 1",[$this->now()])->fetch();if(!$r)return null;$attempt=(string)Str::uuid();$this->store->run("UPDATE moderation_queue SET notification='sending',retry_count=retry_count+1,attempt=? WHERE artwork=?",[$attempt,$r['artwork']]);return $r+['attempt'=>$attempt];});}
 public function delivered(string $id,string $attempt,string $messageId):bool {if(!preg_match('/^\d{1,32}$/D',$messageId))throw new \InvalidArgumentException('Invalid receipt');return $this->store->transaction(function()use($id,$attempt,$messageId){$r=$this->row($id);if(!$r||$r['attempt']!==$attempt||$r['notification']!=='sending')return false;$now=$this->now();$this->store->run("UPDATE moderation_queue SET notification='delivered',message_id=?,delivered_at=?,due_at=?,revision=revision+1 WHERE artwork=?",[$messageId,$now,$r['status']==='pending'?$now+8*3600000:null,$id]);$this->audit($id,'system:notification','delivered');return true;});}
 public function uncertain(string $id,string $attempt):bool {return $this->store->transaction(function()use($id,$attempt){$r=$this->row($id);if(!$r||$r['attempt']!==$attempt||$r['notification']!=='sending')return false;$this->store->run("UPDATE moderation_queue SET notification='uncertain',due_at=NULL,revision=revision+1 WHERE artwork=?",[$id]);$this->audit($id,'system:notification','uncertain');return true;});}
 public function recoverInterrupted():int {return $this->store->transaction(function(){$rows=$this->store->run("SELECT artwork FROM moderation_queue WHERE notification='sending'")->fetchAll();foreach($rows as $r){$this->store->run("UPDATE moderation_queue SET notification='uncertain',due_at=NULL,revision=revision+1 WHERE artwork=?",[$r['artwork']]);$this->audit($r['artwork'],'system:notification','interrupted');}return count($rows);});}
 public function decide(string $actor,string $id,string $action,int $revision,string $reason=''):array {$this->staff($actor);abort_unless(in_array($action,['approve','deny','hold'],true)&&$revision>=0&&mb_strlen($reason)<=500&&!preg_match('/[\x00-\x1f\x7f]/',$reason),400);return $this->store->transaction(function()use($actor,$id,$action,$revision,$reason){$r=$this->row($id);abort_unless($r&&(int)$r['revision']===$revision&&in_array($r['status'],['pending','held'],true),409);$status=match($action){'approve'=>'published','deny'=>'denied','hold'=>'held'};if($action==='approve')$this->publish($id);else $this->store->run("UPDATE artworks SET status=?,visibility='private' WHERE id=?",[$status,$id]);$this->store->run('UPDATE moderation_queue SET due_at=NULL,revision=revision+1 WHERE artwork=?',[$id]);$this->audit($id,$actor,$action,trim($reason));return ['status'=>$status];});}
 public function autoapprove():int {return $this->store->transaction(function(){$rows=$this->store->run("SELECT q.artwork FROM moderation_queue q JOIN artworks a ON a.id=q.artwork WHERE q.notification='delivered' AND q.due_at<=? AND a.status='pending' LIMIT 100",[$this->now()])->fetchAll();foreach($rows as $r){$this->publish($r['artwork']);$this->store->run('UPDATE moderation_queue SET due_at=NULL,revision=revision+1 WHERE artwork=?',[$r['artwork']]);$this->audit($r['artwork'],'system:autoapproval','approve');}return count($rows);});}
}

